custom_css:
/* 新芽主题作者：@jiuyi0204。未经许可，禁止二次修改、二次上传。 */

/*
 * 新芽 · SillyTavern 1.14.0 原生布局约束
 * 不改写 sheld、drawer-content、send_form 的 display/position/width/height。
 * 左右停靠面板完全使用官方 sheldWidth 计算。
 */

#chat .mes:not([is_system="true"]) {
    max-width: 1120px;
    margin-inline: auto;
}

/* 官方 .mes 保持 flex。角色正文占满消息宽度，右侧头像只占标题区。 */
#chat .mes[is_user="false"] > .mes_block {
    order: 1;
    flex: 1 1 100%;
    width: 100%;
    min-width: 0;
    padding-right: 0;
}

#chat .mes[is_user="false"] > .mesAvatarWrapper {
    order: 2;
    position: absolute;
    top: 2px;
    right: 8px;
    flex: none;
    margin: 0;
}

#chat .mes[is_user="true"] > .mesAvatarWrapper {
    margin-right: 2px;
}

/*
 * 新芽 · SillyTavern UI Theme
 * 目标版本：1.14.0；只覆盖视觉变量，不重建官方页面布局。
 */

@font-face {
    font-family: "LXGW WenKai";
    src: url("https://cdn.jsdelivr.net/gh/jiuyi777/sillytavern-theme-assets@b687607c927d8ef25c1a98e3d82c05231924c2ba/font-library/v2/fonts/lxgwwenkai/lxgwwenkai.woff2") format("woff2");
    font-style: normal;
    font-weight: 400;
    font-display: swap;
}

@font-face {
    font-family: "Zhuque Fangsong";
    src: url("https://cdn.jsdelivr.net/gh/jiuyi777/sillytavern-theme-assets@b687607c927d8ef25c1a98e3d82c05231924c2ba/font-library/v2/fonts/zhuquefangsong/zhuquefangsong.woff2") format("woff2");
    font-style: normal;
    font-weight: 400;
    font-display: swap;
}

@font-face {
    font-family: "Source Han Serif SC";
    src: url("https://cdn.jsdelivr.net/gh/jiuyi777/sillytavern-theme-assets@b687607c927d8ef25c1a98e3d82c05231924c2ba/font-library/v2/fonts/sourcehanserifsc/sourcehanserifsc.woff2") format("woff2");
    font-style: normal;
    font-weight: 400;
    font-display: swap;
}

:root {
    --xy-deep: #2e6a67;
    --xy-mid: #5e8c87;
    --xy-mist: #a9c8be;
    --xy-pale: #d7e6db;
    --xy-paper: #f3f1e9;
    --xy-paper-strong: #faf9f3;
    --xy-paper-soft: #f6f5ee;
    --xy-ink: #18312f;
    --xy-text: #30423f;
    --xy-muted: #6f7e79;
    --xy-danger: #a45f56;
    --xy-border: rgba(94, 140, 135, 0.42);
    --xy-border-soft: rgba(94, 140, 135, 0.20);
    --xy-shadow: 0 8px 24px rgba(35, 66, 62, 0.10);
    --xy-shadow-soft: 0 3px 12px rgba(35, 66, 62, 0.08);
    --xy-radius-sm: 9px;
    --xy-radius-md: 14px;
    --xy-radius-lg: 18px;
    --xy-font-serif: "Zhuque Fangsong", "Source Han Serif SC", "Noto Serif CJK SC", "Songti SC", SimSun, serif;
    --xy-font-title: "LXGW WenKai", "Zhuque Fangsong", "Source Han Serif SC", serif;
    --xy-font-ui: "Microsoft YaHei UI", "Noto Sans CJK SC", "Source Han Sans SC", system-ui, sans-serif;
    --xy-font-mono: "Cascadia Mono", "JetBrains Mono", Consolas, monospace;
    --mainFontFamily: var(--xy-font-serif);
    --xy-avatar-frame-a: url("https://cdn.jsdelivr.net/gh/jiuyi777/sillytavern-theme-assets@b687607c927d8ef25c1a98e3d82c05231924c2ba/assets/xinya/variants/avatar-frames/avatar-A.png");
    --xy-avatar-frame-b: url("https://cdn.jsdelivr.net/gh/jiuyi777/sillytavern-theme-assets@b687607c927d8ef25c1a98e3d82c05231924c2ba/assets/xinya/variants/avatar-frames/avatar-B.png");
    --xy-avatar-frame-c: url("https://cdn.jsdelivr.net/gh/jiuyi777/sillytavern-theme-assets@b687607c927d8ef25c1a98e3d82c05231924c2ba/assets/xinya/variants/avatar-frames/avatar-C.png");
    --xy-avatar-frame-d: url("https://cdn.jsdelivr.net/gh/jiuyi777/sillytavern-theme-assets@b687607c927d8ef25c1a98e3d82c05231924c2ba/assets/xinya/variants/avatar-frames/avatar-D.png");
    --xy-avatar-frame-e: url("https://cdn.jsdelivr.net/gh/jiuyi777/sillytavern-theme-assets@b687607c927d8ef25c1a98e3d82c05231924c2ba/assets/xinya/variants/avatar-frames/avatar-E.png");
    --xy-avatar-frame-f: url("https://cdn.jsdelivr.net/gh/jiuyi777/sillytavern-theme-assets@b687607c927d8ef25c1a98e3d82c05231924c2ba/assets/xinya/variants/avatar-frames/avatar-F.png");
    --xy-avatar-frame: var(--xy-avatar-frame-a);
    --xy-sprout: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/aa7ebc5ccc211eb7e027c6b1b0bc8915b4ed0e15/assets/xinya/sprout-divider.png");
    --xy-leaf-light: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/aa7ebc5ccc211eb7e027c6b1b0bc8915b4ed0e15/assets/xinya/send-leaf.png");
}

body {
    color: var(--xy-text);
    background-color: var(--xy-paper);
    background-image:
        radial-gradient(circle at 12% 10%, rgba(215, 230, 219, 0.42), transparent 28%),
        radial-gradient(circle at 88% 86%, rgba(169, 200, 190, 0.22), transparent 30%),
        linear-gradient(135deg, #f8f7f1, var(--xy-paper));
    font-family: var(--xy-font-serif);
}

:is(#chat, #top-bar, #send_form, .drawer-content, .popup, .options-content, .menu) {
    scrollbar-color: var(--xy-mist) transparent;
}

:is(#chat, #top-bar, #send_form, .drawer-content, .popup, .options-content, .menu) :focus-visible {
    outline: 2px solid var(--xy-deep);
    outline-offset: 2px;
}

::selection {
    color: var(--xy-ink);
    background: rgba(169, 200, 190, 0.52);
}

/* ================================================================
   W01 页面背景与主聊天
   ================================================================ */
#sheld {
    border-inline: 1px solid var(--xy-border-soft);
}

#chat {
    --xy-chat-avatar-size: 64px;
    --xy-chat-avatar-frame-size: 82px;
    --xy-chat-avatar-frame-offset: -9px;
    color: var(--xy-text);
    background:
        linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.50) 7%, rgba(255, 255, 255, 0.50) 93%, transparent),
        rgba(241, 240, 232, 0.82);
    text-shadow: none;
}

#chat .mes:not([is_system="true"]) {
    padding-top: 14px;
    padding-bottom: 10px;
    color: var(--xy-text);
    background: transparent;
}

#chat .mes[is_user="true"] {
    padding-bottom: 2px;
}

#chat .mes[is_user="false"] {
    padding-top: 2px;
    padding-bottom: 20px;
}

#chat .mes:not([is_system="true"]) > .mesAvatarWrapper {
    overflow: visible;
}

#chat .mes[is_user="true"] > .mesAvatarWrapper {
    position: relative;
}

#chat .mes:not([is_system="true"]) > .mesAvatarWrapper::after {
    content: "";
    position: absolute;
    z-index: 2;
    top: var(--xy-chat-avatar-frame-offset);
    left: var(--xy-chat-avatar-frame-offset);
    width: var(--xy-chat-avatar-frame-size);
    height: var(--xy-chat-avatar-frame-size);
    background: var(--xy-avatar-frame) center / contain no-repeat;
    pointer-events: none;
}

/* 只镜像 User 的装饰层；用户头像图片保持原方向。 */
#chat .mes[is_user="true"] > .mesAvatarWrapper::after {
    transform: scaleX(-1);
}

#chat .mes:not([is_system="true"]) .avatar,
#chat .mes:not([is_system="true"]) .avatar img {
    width: var(--xy-chat-avatar-size);
    height: var(--xy-chat-avatar-size);
    border-radius: 50%;
    clip-path: circle(50% at 50% 50%);
}

#chat .mes:not([is_system="true"]) .avatar {
    flex: 0 0 var(--xy-chat-avatar-size);
    overflow: hidden;
}

#chat .mes:not([is_system="true"]) .avatar img {
    border: 2px solid rgba(94, 140, 135, 0.72);
    object-fit: cover;
    object-position: center;
    box-shadow: inset 0 0 0 1px rgba(250, 249, 243, 0.82);
}

#chat .mesIDDisplay,
#chat .mes_timer,
#chat .tokenCounterDisplay {
    color: var(--xy-muted);
    font-family: var(--xy-font-ui);
    font-size: 10px;
    text-align: center;
}

#chat .mes:not([is_system="true"]) > .mes_block {
    color: var(--xy-text);
    overflow-x: hidden;
}

#chat .mes[is_user="true"] > .mes_block {
    padding-left: 12px;
}

#chat .mes[is_user="false"] > .mes_block {
    border-top: 1px solid var(--xy-border-soft);
    background: linear-gradient(90deg, rgba(215, 230, 219, 0.24), rgba(250, 249, 243, 0.52) 35%, transparent);
}

#chat .mes:not([is_system="true"]) > .mes_block::after {
    content: "新芽";
    display: block;
    width: 210px;
    max-width: 58%;
    height: 22px;
    margin: 9px auto 0;
    padding-left: 158px;
    color: var(--xy-mid);
    background: var(--xy-sprout) left center / 150px auto no-repeat;
    font: 12px/22px var(--xy-font-title);
    letter-spacing: 0.12em;
    white-space: nowrap;
    box-sizing: border-box;
    opacity: 0.88;
    pointer-events: none;
}

#chat .ch_name {
    color: var(--xy-deep);
    font-family: var(--xy-font-title);
}

#chat .mes[is_user="false"] .ch_name {
    padding-bottom: 5px;
    border-bottom: 1px solid var(--xy-border-soft);
}

#chat .name_text {
    color: var(--xy-deep);
    font-family: var(--xy-font-title);
    font-weight: 500;
    letter-spacing: 0.07em;
}

#chat .timestamp {
    color: var(--xy-muted);
    font-family: var(--xy-font-ui);
}

#chat :is(.mes_text, .mes_reasoning) {
    color: var(--xy-text);
    font-family: var(--xy-font-serif);
    font-size: clamp(16px, 1.02vw, 18px);
    font-weight: 400;
    line-height: 1.88;
    letter-spacing: 0.02em;
}

#chat .mes[is_user="true"] :is(.mes_text, .mes_reasoning) {
    margin-top: 2px;
    padding: 6px 12px 6px 16px;
    border-left: 3px solid var(--xy-mist);
    color: var(--xy-ink);
    background: linear-gradient(90deg, rgba(250, 249, 243, 0.72), transparent 88%);
    line-height: 1.72;
}

/* Character 使用居中的正常阅读宽度；不改写正文内部卡片或选项布局。 */
#chat .mes[is_user="false"] :is(.mes_text, .mes_reasoning) {
    width: 100%;
    max-width: 46rem;
    min-height: 0;
    height: auto;
    margin-inline: auto;
    padding-inline: 18px;
    box-sizing: border-box;
    background: transparent;
}

#chat .mes[is_user="false"] .ch_name {
    padding-right: calc(var(--xy-chat-avatar-size) + 20px);
}

/* 思维折叠条沿用纸张色，不再出现与浅色主题割裂的黑块。 */
#chat .mes_reasoning_header {
    color: var(--xy-deep);
    border: 1px solid var(--xy-border-soft);
    background-color: #edf1eb;
    box-shadow: none;
    text-shadow: none;
}

#chat .mes_reasoning_header:hover,
#chat .mes_reasoning_details[open] .mes_reasoning_header {
    color: var(--xy-ink);
    border-color: var(--xy-border);
    background-color: #e2ebe3;
}

#chat .mes_reasoning_arrow {
    color: var(--xy-deep);
    opacity: 1;
    filter: none;
}

#chat :is(.mes_text, .mes_reasoning) blockquote {
    margin: 0.8em 0;
    padding: 10px 14px;
    border-left: 2px solid var(--xy-mid);
    color: var(--xy-ink);
    background: rgba(215, 230, 219, 0.46);
}

#chat :is(.mes_text, .mes_reasoning) hr {
    height: 22px;
    border: 0;
    background: var(--xy-sprout) center / min(260px, 70%) 22px no-repeat;
    opacity: 0.82;
}

#chat :is(.mes_text, .mes_reasoning) pre {
    border: 1px solid var(--xy-border);
    border-radius: var(--xy-radius-sm);
    background: #e9eee8;
    box-shadow: inset 3px 0 0 var(--xy-mid);
}

#chat :is(.mes_text, .mes_reasoning) :is(pre, code) {
    font-family: var(--xy-font-mono);
}

#chat .mes_buttons,
#chat .mes_edit_buttons,
#chat .mes_reasoning_actions {
    color: var(--xy-deep);
    filter: none;
    text-shadow: none;
}

/* SillyTavern defaults these actions to opacity .3/.5 plus a black drop-shadow.
   Keep the native controls and hit areas, but make their icons crisp and legible. */
#chat .mes_button,
#chat .extraMesButtons > div,
#chat .mes_edit_buttons .menu_button,
#chat .mes_reasoning_actions .edit_button {
    color: var(--xy-deep);
    opacity: 0.9;
    filter: none;
    text-shadow: none;
}

#chat :is(.mes_button, .extraMesButtons > div, .mes_edit_buttons .menu_button, .mes_reasoning_actions .edit_button):hover {
    color: var(--xy-deep);
    opacity: 1;
    filter: none;
}

#chat .mes_edit_buttons .menu_button {
    border: 1px solid var(--xy-border);
    background-color: rgba(250, 249, 243, 0.96);
    box-shadow: none;
}

#chat .mes_edit_done.menu_button {
    color: #fff;
    border-color: var(--xy-deep);
    background-color: var(--xy-deep);
}

#chat .mes_edit_cancel.menu_button {
    color: #fff;
    border-color: #8b5f5b;
    background-color: #8b5f5b;
}

#chat :is(.reasoning_edit_textarea, .edit_textarea) {
    color: var(--xy-ink);
    border: 1px solid var(--xy-border);
    background-color: rgba(250, 249, 243, 0.98);
    box-shadow: inset 3px 0 0 var(--xy-mist);
    opacity: 1;
    filter: none;
    text-shadow: none;
}

#chat .mes[is_system="true"] {
    margin: 8px auto;
    border: 1px dashed var(--xy-border);
    border-radius: var(--xy-radius-md);
    color: var(--xy-muted);
    background: rgba(250, 249, 243, 0.76);
}

/* ================================================================
   W02 顶栏
   ================================================================ */
#top-bar {
    color: var(--xy-deep);
    border-bottom: 1px solid var(--xy-border-soft);
    border-radius: 0 0 var(--xy-radius-md) var(--xy-radius-md);
    background-color: rgba(250, 249, 243, 0.94);
    box-shadow: var(--xy-shadow-soft);
    text-shadow: none;
}

#top-settings-holder :is(.drawer-icon, .drawer-toggle, .interactable) {
    border: 1px solid transparent;
    border-radius: 9px;
    color: var(--xy-mid);
    text-shadow: none;
}

#top-settings-holder :is(.drawer-icon, .drawer-toggle, .interactable):hover,
#top-settings-holder .openIcon {
    border-color: var(--xy-border);
    color: var(--xy-deep);
    background: rgba(215, 230, 219, 0.50);
    filter: none;
}

#ai-config-button,
#sys-settings-button,
#advanced-formatting-button,
#WI-SP-button,
#user-settings-button,
#backgrounds-button,
#extensions-settings-button,
#persona-management-button,
#rightNavHolder {
    background-color: rgba(241, 240, 232, 0.62);
}

/* ================================================================
   W03 输入区与发送键
   ================================================================ */
#send_form {
    position: relative;
    color: var(--xy-text);
    border-color: var(--xy-border);
    border-radius: var(--xy-radius-lg);
    background-color: rgba(250, 249, 243, 0.96);
    box-shadow: inset 0 0 0 3px rgba(169, 200, 190, 0.10), var(--xy-shadow-soft);
    text-shadow: none;
}

#send_form::before,
#send_form::after {
    content: "";
    position: absolute;
    width: 20px;
    height: 20px;
    pointer-events: none;
}

#send_form::before {
    top: 5px;
    left: 5px;
    border-top: 1px solid var(--xy-mid);
    border-left: 1px solid var(--xy-mid);
}

#send_form::after {
    right: 5px;
    bottom: 5px;
    border-right: 1px solid var(--xy-mid);
    border-bottom: 1px solid var(--xy-mid);
}

#send_textarea {
    margin: 0;
    padding: 11px 13px;
    border-color: var(--xy-border);
    border-radius: 11px;
    color: var(--xy-ink);
    background: rgba(241, 240, 232, 0.72);
    box-shadow: inset 0 0 0 2px rgba(169, 200, 190, 0.08);
    font-family: var(--xy-font-serif);
    line-height: 1.62;
    text-shadow: none;
}

#send_textarea::placeholder {
    color: rgba(82, 98, 94, 0.70);
}

#send_form:focus-within {
    border-color: var(--xy-deep);
}

#leftSendForm > div,
#rightSendForm > div {
    border-radius: 10px;
    color: var(--xy-deep);
}

#leftSendForm > div:hover,
#rightSendForm > div:hover {
    color: var(--xy-deep);
    background-color: rgba(215, 230, 219, 0.58);
    filter: none;
}

#options_button,
#extensionsMenuButton {
    border: 1px solid var(--xy-border);
    background: linear-gradient(145deg, var(--xy-paper-strong), rgba(215, 230, 219, 0.72));
}

#send_but.fa-paper-plane {
    color: var(--xy-deep);
    border-color: transparent;
    background: transparent;
}

#send_but.fa-paper-plane::before {
    color: currentColor;
    opacity: 1;
}

#send_form .mes_stop {
    color: #fff;
    background-color: var(--xy-danger);
}

#options,
#extensionsMenu {
    color: var(--xy-text);
    border: 1px solid var(--xy-border);
    border-radius: var(--xy-radius-md);
    background: rgba(250, 249, 243, 0.98);
    box-shadow: var(--xy-shadow);
    text-shadow: none;
}

/* ================================================================
   通用控件与抽屉视觉层：不覆盖原生宽度、定位、显示和滚动规则
   ================================================================ */
.drawer-content {
    color: var(--xy-text);
    border-color: var(--xy-border);
    background:
        linear-gradient(var(--xy-mid), var(--xy-mid)) left 8px top 8px / 24px 1px no-repeat,
        linear-gradient(var(--xy-mid), var(--xy-mid)) left 8px top 8px / 1px 24px no-repeat,
        linear-gradient(var(--xy-mid), var(--xy-mid)) right 8px bottom 8px / 24px 1px no-repeat,
        linear-gradient(var(--xy-mid), var(--xy-mid)) right 8px bottom 8px / 1px 24px no-repeat,
        rgba(250, 249, 243, 0.97);
    box-shadow: var(--xy-shadow);
    text-shadow: none;
}

:is(.drawer-content, .popup, #options, #extensionsMenu)
    :is(input:not([type="range"]):not([type="checkbox"]):not([type="radio"]), textarea, select) {
    color: var(--xy-ink);
    border-color: var(--xy-border);
    background-color: rgba(250, 249, 243, 0.86);
    font-family: var(--xy-font-ui);
    box-shadow: inset 0 0 0 1px rgba(169, 200, 190, 0.07);
}

/* XY_NATIVE_OPTION_OVERRIDE_START
   Chromium paints the opened native list outside the visible drawer subtree.
   The two color declarations mirror the working treatment in 苦昼短-灰 and
   intentionally outrank SillyTavern 1.14.0's dark option:not(:checked) rule. */
select option,
select optgroup,
select option:not(:checked) {
    color: #344541 !important;
    background-color: #faf9f3 !important;
}

select option:checked {
    color: #173f3c !important;
    background-color: #d7e6db !important;
}
/* XY_NATIVE_OPTION_OVERRIDE_END */

:is(.drawer-content, .popup, #options, #extensionsMenu) :is(input[type="range"], input[type="checkbox"], input[type="radio"]) {
    accent-color: var(--xy-deep);
}

:is(.drawer-content, .popup, #options, #extensionsMenu) :is(.menu_button, button) {
    color: var(--xy-deep);
    border-color: var(--xy-border);
    border-radius: var(--xy-radius-sm);
    background-color: rgba(241, 240, 232, 0.90);
    text-shadow: none;
}

:is(.drawer-content, .popup, #options, #extensionsMenu) :is(.menu_button, button):hover {
    border-color: var(--xy-deep);
    background-color: rgba(215, 230, 219, 0.70);
    filter: none;
}

.inline-drawer-header,
.standoutHeader {
    position: relative;
    margin-block: 4px;
    padding: 7px 36px 7px 10px;
    border: 1px solid var(--xy-border-soft);
    border-radius: 10px;
    color: var(--xy-deep);
    background: linear-gradient(90deg, rgba(215, 230, 219, 0.62), rgba(241, 240, 232, 0.58));
}

.inline-drawer-header::before,
.standoutHeader::before {
    content: "";
    position: absolute;
    top: 50%;
    right: 7px;
    width: 26px;
    height: 18px;
    transform: translateY(-50%);
    background: var(--xy-sprout) center / contain no-repeat;
    opacity: 0.72;
    pointer-events: none;
}

.drawer-content :is(h2, h3, h4),
.popup :is(h2, h3, h4) {
    color: var(--xy-deep);
    font-family: var(--xy-font-title);
    font-weight: 500;
    letter-spacing: 0.05em;
}

.dragClose,
.floating_panel_close,
.popup-button-close,
#logprobsViewerClose {
    border: 1px solid rgba(164, 95, 86, 0.42);
    border-radius: 9px;
    color: var(--xy-danger);
    background: rgba(250, 249, 243, 0.90);
}

.right_menu_button,
.inline-drawer-icon,
.logprobs_panel_control_button {
    border-radius: 8px;
    color: var(--xy-mid);
    text-shadow: none;
}

/* ================================================================
   W04 文本补全参数
   ================================================================ */
#left-nav-panel :is(.range-block, .range-block-range, .range-block-range-and-counter, .settingsSectionWrap) {
    margin-block: 5px;
    border-color: var(--xy-border-soft);
    border-radius: 9px;
