/* ================================================================
   W06 AI 回复格式
   ================================================================ */
#AdvancedFormatting {
    background-color: #faf9f3;
}

#AdvancedFormatting textarea {
    line-height: 1.58;
}

#AdvancedFormatting .inline-drawer-content {
