    background-color: rgba(250, 249, 243, 0.54);
}

#AdvancedFormatting :is(.inline-drawer-header, .standoutHeader) {
    color: var(--xy-deep);
    border-color: var(--xy-border-soft);
    background: linear-gradient(90deg, rgba(215, 230, 219, 0.58), rgba(241, 240, 232, 0.48));
    filter: none;
    text-shadow: none;
}

#AdvancedFormatting :is(textarea, input:not([type="range"]):not([type="checkbox"]):not([type="radio"]), select) {
    color: var(--xy-ink);
    border-color: var(--xy-border);
    background-color: rgba(250, 249, 243, 0.96);
    opacity: 1;
    filter: none;
    text-shadow: none;
}

#AdvancedFormatting :is(textarea, input:not([type="range"]):not([type="checkbox"]):not([type="radio"]), select):disabled {
    color: var(--xy-muted);
    background-color: rgba(231, 235, 227, 0.96);
    opacity: 1;
    filter: none;
}

#AdvancedFormatting .disabled {
    color: var(--xy-muted);
    opacity: 0.9;
    filter: none;
}

#completion_prompt_manager,
#completion_prompt_manager #completion_prompt_manager_list {
