}

#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt:hover {
    border-color: var(--xy-border);
    background-color: #edf1e9;
}

#completion_prompt_manager :is(.completion_prompt_manager_header, .completion_prompt_manager_header_advanced span, .fa-solid) {
    color: var(--xy-deep);
    opacity: 1;
    filter: none;
    text-shadow: none;
