#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt .completion_prompt_manager_prompt_name .prompt-manager-inspect-action {
    color: var(--xy-text);
    opacity: 1;
    filter: none;
    text-shadow: none;
}

#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name,
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name .prompt-manager-inspect-action {
    color: #52645f;
}

#completion_prompt_manager .completion_prompt_manager_header,
#completion_prompt_manager .completion_prompt_manager_header_advanced span {
    color: var(--xy-deep);
    opacity: 1;
    filter: none;
    text-shadow: none;
}

#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt .completion_prompt_manager_prompt_name > .fa-solid {
    color: var(--xy-deep);
    opacity: 1;
    filter: none;
    text-shadow: none;
}

/* 精确压过官方 span span span 的 opacity:.4 与黑色 drop-shadow。 */
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt > span > .prompt_manager_prompt_controls > span {
    color: var(--xy-deep);
    opacity: 1;
    filter: none;
    text-shadow: none;
