}

#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt.completion_prompt_manager_prompt_disabled > span > .prompt_manager_prompt_controls > .prompt-manager-toggle-action {
    color: #526a64;
}

#AdvancedFormatting input[type="checkbox"] {
    color: #f8fbf7;
    border-color: var(--xy-deep);
    background-color: #f8fbf7;
    box-shadow: none;
    opacity: 1;
    filter: none;
}

#AdvancedFormatting input[type="checkbox"]:checked {
    background-color: var(--xy-deep);
}

#AdvancedFormatting code,
#completion_prompt_manager code {
    padding: 1px 6px;
    color: #f8fbf7;
    border: 1px solid #244f4d;
    border-radius: 5px;
    background-color: var(--xy-deep);
    box-shadow: none;
    text-shadow: none;
}

/* ================================================================
   W07 世界书
   ================================================================ */
#WorldInfo {
    background-color: #faf9f3;
}

#WorldInfo :is(.world_entry, .wi-card, .settingsSectionWrap) {
    margin-block: 3px;
    border: 1px solid var(--xy-border-soft);
    border-left: 3px solid var(--xy-mid);
    border-radius: 8px;
    background-color: #faf9f3;
    box-shadow: none;
}

#WorldInfo .world_entry .inline-drawer-header {
    min-height: 0;
    margin-block: 0;
    padding: 4px 6px;
    border: 0;
    border-radius: 7px;
    background: rgba(241, 240, 232, 0.46);
    line-height: 1.16;
}

#WorldInfo .world_entry .inline-drawer-header::before {
    content: none;
}

#WorldInfo :is(input:not([type="range"]):not([type="checkbox"]):not([type="radio"]), textarea, select, .select2-selection) {
    color: var(--xy-ink);
    border-color: var(--xy-border);
    background-color: #faf9f3;
    opacity: 1;
    filter: none;
    text-shadow: none;
}

#WorldInfo :is(input, textarea, select):disabled {
    color: var(--xy-muted);
    background-color: #edf1eb;
    opacity: 1;
    filter: none;
}

#WorldInfo .disabledWIEntry {
    opacity: 0.68;
    filter: none;
}

/* ================================================================
   W08 用户设置
   ================================================================ */
#user-settings-block {
    background-color: #faf9f3;
}

#user-settings-block :is(.settingsSectionWrap, .range-block, fieldset) {
    margin-block: 6px;
    border-color: var(--xy-border-soft);
    border-radius: 10px;
    background-color: #f4f3ec;
}

#user-settings-block :is(#themes, #ui_preset_import_button) {
    border-color: var(--xy-mid);
}

/* Official 1.14.0 applies the dark standout gradient directly to every h4 in
   this panel. Match that selector so the light theme wins by source order. */
#user-settings-block h4 {
    color: var(--xy-deep);
    border-color: var(--xy-border-soft);
    background-color: #f1f0e8;
    background-image: linear-gradient(90deg, rgba(215, 230, 219, 0.90), rgba(250, 249, 243, 0.96));
    box-shadow: none;
    text-shadow: none;
}

/* ================================================================
   W09 背景管理
   ================================================================ */
#Backgrounds :is(.bg_example, .background_select) {
    border: 1px solid var(--xy-border-soft);
    border-radius: 11px;
    background-color: var(--xy-paper-soft);
    box-shadow: none;
}

#Backgrounds :is(.bg_example, .background_select):hover {
    border-color: var(--xy-deep);
    box-shadow: var(--xy-shadow-soft);
}

/* ================================================================
   W10 扩展程序
   ================================================================ */
#rm_extensions_block :is(.extension_container, .extensions_block) {
    margin-block: 6px;
    border: 1px solid var(--xy-border-soft);
    border-radius: 10px;
    background-color: rgba(250, 249, 243, 0.66);
}

/* Match and outrank the official 1.14.0 standout-header gradient without
   changing any extension drawer geometry or toggle behavior. */
#rm_extensions_block #extensions_settings .inline-drawer-toggle.inline-drawer-header,
#rm_extensions_block #extensions_settings2 .inline-drawer-toggle.inline-drawer-header,
#rm_extensions_block .standoutHeader.inline-drawer-header,
#rm_extensions_block .standoutHeader,
#rm_extensions_block .inline-drawer-header {
    color: var(--xy-deep);
    border-color: var(--xy-border-soft);
    background-color: #f1f0e8;
    background-image: linear-gradient(90deg, rgba(215, 230, 219, 0.90), rgba(250, 249, 243, 0.96));
    box-shadow: none;
    text-shadow: none;
}

#rm_extensions_block :is(.standoutHeader, .inline-drawer-header):hover {
    color: var(--xy-deep);
    background-image: linear-gradient(90deg, rgba(200, 222, 211, 0.96), rgba(241, 240, 232, 0.98));
    filter: none;
}

/* ================================================================
   W11 Persona
   ================================================================ */
#PersonaManagement .avatar-container {
    border-color: var(--xy-border);
    border-radius: 11px;
    background-color: rgba(250, 249, 243, 0.74);
    box-shadow: none;
}

#PersonaManagement .avatar-container.selected {
    outline: 2px solid var(--xy-mid);
    outline-offset: 2px;
}

/* ================================================================
   W12 角色管理与详情
   ================================================================ */
#right-nav-panel :is(.character_select, .group_select, .avatar-container, .character_select_container) {
    border-color: var(--xy-border-soft);
    border-radius: 11px;
    color: var(--xy-text);
    background-color: rgba(250, 249, 243, 0.74);
    box-shadow: none;
}

#right-nav-panel :is(.character_select, .group_select, .avatar-container):hover {
    border-color: var(--xy-deep);
    background-color: rgba(215, 230, 219, 0.44);
    filter: none;
}

#right-nav-panel .avatar img,
#PersonaManagement .avatar img {
    border-color: var(--xy-border);
    box-shadow: none;
}

/* XY_CHARACTER_TAG_OVERRIDE_START
   Character tags can carry an inline custom background color. This narrowly
   scoped override replaces the red/pink chip without affecting tag behavior. */
#right-nav-panel :is(#tagList, .tags, .tags_inline) .tag {
    color: var(--xy-deep) !important;
    border-color: var(--xy-mid) !important;
    background-color: rgba(215, 230, 219, 0.92) !important;
    opacity: 1;
    filter: none;
    text-shadow: none;
}
/* XY_CHARACTER_TAG_OVERRIDE_END */

#right-nav-panel :is(#tagList, .tags, .tags_inline) .tag .tag_remove {
    color: #8b5f5b;
    opacity: 0.9;
    filter: none;
}

/* ================================================================
   W13 弹窗、通知、菜单
   ================================================================ */
:is(.popup, .popup-content, .popup-body, .popper-modal) {
    color: var(--xy-text);
    border-color: var(--xy-border);
    border-radius: var(--xy-radius-md);
    background-color: rgba(250, 249, 243, 0.98);
    box-shadow: var(--xy-shadow);
    text-shadow: none;
}

body #toast-container > .toast {
    color: var(--xy-text);
    border: 1px solid var(--xy-border);
    border-left: 4px solid var(--xy-mid);
    border-radius: 10px;
    background-color: rgba(250, 249, 243, 0.98);
    background-position: 14px center;
    background-repeat: no-repeat;
    background-size: 18px 18px;
    box-shadow: var(--xy-shadow-soft);
    opacity: 1;
    filter: none;
    text-shadow: none;
}

body #toast-container > .toast-info {
    border-left-color: var(--xy-mid);
}

body #toast-container > .toast-success {
    border-left-color: #6f987b;
}

body #toast-container > .toast-warning {
    border-left-color: #b78942;
}

body #toast-container > .toast-error {
    border-left-color: var(--xy-danger);
}

:is(.list-group, .options-content, .dropdown-content, .select2-dropdown) {
    color: var(--xy-text);
    border-color: var(--xy-border);
    background-color: var(--xy-paper-strong);
    box-shadow: var(--xy-shadow-soft);
}

/* ================================================================
   W14 手机端
   官方 mobile-styles.css 继续负责宽度、定位、抽屉开关与滚动。
   ================================================================ */
@media (max-width: 700px) {
    #chat {
        --xy-chat-avatar-size: 52px;
        --xy-chat-avatar-frame-size: 66px;
        --xy-chat-avatar-frame-offset: -7px;
    }

    #chat .mes:not([is_system="true"]) {
        padding-inline: 7px;
    }

    #chat .mes[is_user="false"] > .mesAvatarWrapper {
        top: 3px;
        right: 8px;
    }

    #chat :is(.mes_text, .mes_reasoning) {
        font-size: 15px;
        line-height: 1.78;
    }

    #chat .mes[is_user="true"] :is(.mes_text, .mes_reasoning) {
        padding-left: 12px;
    }

    /* 手机长 RP 使用完整、居中的可读正文列，不再用大内边距硬挤窄。 */
    #chat .mes[is_user="false"] :is(.mes_text, .mes_reasoning) {
        width: 100%;
        max-width: 100%;
        margin-inline: auto;
        padding-inline: 14px;
    }

    #left-nav-panel .drawer-content {
        border: 2px solid rgba(94, 140, 135, 0.52);
    }

    #openai_api-presets {
        padding: 6px;
        border: 2px solid rgba(94, 140, 135, 0.42);
        border-radius: 11px;
        background-color: #faf9f3;
    }

    #left-nav-panel #openai_api-presets #settings_preset_openai {
        color: var(--xy-ink);
        border: 2px solid var(--xy-border);
        background-color: #f7f5ee;
        opacity: 1;
        filter: none;
        text-shadow: none;
    }

    #send_form {
        border-radius: 14px;
    }

    #send_textarea {
        padding: 9px 10px;
    }

    .drawer-content {
        border-radius: 0 0 16px 16px;
    }
}

@media (prefers-reduced-motion: reduce) {
    :is(#chat, #top-bar, #send_form, .drawer-content, .popup, .options-content, .menu) {
        scroll-behavior: auto;
    }
}

/*
 * 远程素材失败时，原头像、文字、原生 Font Awesome 图标和按钮点击区继续存在。
 */
#chat .mes:not([is_system="true"]) .avatar {
    outline: 1px solid var(--xy-border-soft);
    outline-offset: 1px;
}

#send_but {
    outline: 1px solid rgba(46, 106, 103, 0.16);
    outline-offset: 1px;
}
